    title: 'The Continuity Equation',
    branchId: 'fluid-mechanics',
    level: 'Undergraduate 1',
    summary: 'Conservation of mass expressed locally: the rate of change of density inside a volume is balanced by flux through its boundary.',
    prerequisites: ['vector-calculus', 'fluid-dynamics'],
